mapper.select:
SELECT FORMAT(IFNULL((
SELECT SUM(bs.endvalue * bscr.signal)
FROM balancesheet bs
JOIN balancesheetcalrelationbasic bscr ON bs.oneitem = bscr.oneitem
JOIN balancesheetcalbasic bscb ON bscr.calcellid = bscb.calcellid
WHERE bs.USERUNIQUE = #{userUnique}
AND bs.PERIOD = #{period}
AND bscb.calcellid = (
SELECT calcellid
FROM balancesheetcalbasic
WHERE calrow_last = 13
AND calcol_last = 6
)
), 0), 2) AS result;
